            'germany' => ['en'=>'The OECD identifies no complete one-stop shop for business creation and recommends harmonised, simpler planning, procurement and approval procedures.','de'=>'Nach Einschätzung der OECD fehlt eine zentrale Anlaufstelle, die eine Unternehmensgründung von Anfang bis Ende begleitet. Außerdem sollten Planungs-, Vergabe- und Genehmigungsverfahren stärker vereinheitlicht und vereinfacht werden.'],
            'cases' => [
                ['country'=>['en'=>'Denmark / Netherlands','de'=>'Dänemark / Niederlande'],'model'=>['en'=>'Single business portals and reusable company data organise compliance around user journeys.','de'=>'Zentrale Unternehmensportale bündeln Gründung, Pflichtmeldungen und Beratung. Bereits geprüfte Firmendaten können für weitere Verfahren wiederverwendet werden.'],'tradeoff'=>['en'=>'Central portals fail if underlying law, registers and responsibilities remain fragmented.','de'=>'Ein gemeinsames Portal hilft wenig, wenn dahinter weiterhin unterschiedliche Gesetze, Register und Zuständigkeiten gelten.']],
                ['country'=>['en'=>'New Zealand / Switzerland','de'=>'Neuseeland / Schweiz'],'model'=>['en'=>'Regulatory impact checks and consultation make costs visible before and after adoption.','de'=>'Regulierungsfolgenabschätzung und Konsultation machen Kosten vor und nach der Einführung sichtbar.'],'tradeoff'=>['en'=>'Review processes themselves can add delay unless proportionate to risk.','de'=>'Prüfverfahren können selbst verzögern, wenn sie nicht risikogerecht sind.']],
